<?php if(!isset($admin,$row,$c)){http_response_code(404);exit;} $days=[1=>'Monday',2=>'Tuesday',3=>'Wednesday',4=>'Thursday',5=>'Friday',6=>'Saturday',0=>'Sunday'];$state=pbx_schedule::office($row,$c['timezone']); ?>
<h3><?= $e($departmentName(($row['name']??'Company Group'))) ?></h3><p><strong><?= $state['open']?'Open now':($state['holiday']?'Closed for a holiday':($state['break']?'On a break':'Closed now')) ?></strong><?php if($state['expires']): ?> · Override ends <?= $e((new DateTimeImmutable('@'.$state['expires']))->setTimezone(new DateTimeZone(($row['timezone']??$c['timezone'])))->format('D H:i')) ?><?php endif; ?></p>
<div class="setup-fields"><?php $select('timezone','Timezone',array_combine(DateTimeZone::listIdentifiers(),DateTimeZone::listIdentifiers()),($row['timezone']??$c['timezone']));$check('always_open','Always Open',($row['hours']['type']??'')==='AllHours'); ?></div>
<p>Add a period for each opening time. An end time earlier than the start continues into the next day. Use 24:00 for midnight.</p>
<?php foreach(['periods'=>['Opening Times',$row['hours']['periods']??[]],'break_periods'=>['Breaks',$row['breaks']['periods']??[]]] as $field=>[$title,$periods]): ?><h3><?= $title ?></h3><div class="setup-table-wrap"><table class="setup-table admin-hours"><thead><tr><th>Use</th><th>Day</th><th>From</th><th>To</th></tr></thead><tbody><?php $periods=array_values($periods);$count=min(56,max(count($periods)+3,$field==='periods'?10:4));for($i=0;$i<$count;$i++):$p=$periods[$i]??[]; ?><tr><td><?php $check($field.'['.$i.'][enabled]','Use',isset($p['day'])); ?></td><td><?php $select($field.'['.$i.'][day]','Day',$days,$p['day']??1); ?></td><td><?php $input($field.'['.$i.'][start]','From',$p['start']??'08:00','time'); ?></td><td><?php $input($field.'['.$i.'][end]','To',$p['end']??'17:00','text','pattern="(?:[01][0-9]|2[0-3]):[0-5][0-9]|24:00" placeholder="17:00"'); ?></td></tr><?php endfor; ?></tbody></table></div><?php endforeach; ?>
<h3>Holidays</h3><label>One date per line, followed by an optional name<textarea name="holidays" rows="5" placeholder="2026-12-25 Christmas"><?= $e(implode("\n",array_map(fn($h)=>$h['date'].' '.($h['name']??''),$row['holidays']??[]))) ?></textarea></label>
<h3>Temporary Opening Hours</h3><?php $check('apply_override','Change the temporary opening status'); ?><div class="setup-fields"><?php $select('office_override','Opening Status',['automatic'=>'Follow Office Hours','open'=>'Force Open','closed'=>'Force Closed'],'automatic');$select('override_minutes','For',['15'=>'15 minutes','30'=>'30 minutes','60'=>'1 hour','240'=>'4 hours','1440'=>'24 hours'],'60'); ?></div><p>When the time ends, your normal hours apply automatically. Emergency routes are managed separately.</p>
